B.alg=new A.r("Deepfakes use AI to create realistic fake videos, audio, or images. Attackers use them to impersonate friends, family, or authority figures.",null,null,null,null,null,null,null,null,null)
B.Fp=new A.r("Why They Are Dangerous",null,B.S,null,null,null,null,null,null,null)
